(1412, 'CPU LGA1851 ↔ Mainboard LGA1851', 57, 57, 1, 1, 2, 'socket', 'socket', 'EQ', 'TƯƠNG THÍCH: CPU LGA1851 (Intel Arrow Lake Core Ultra Series 2) tương thích hoàn hảo với Mainboard chuẩn socket LGA1851.', 'ACTIVE', 1, '2026-10-15 13:45:24', '2026-10-15 13:45:24'),
(1413, 'CPU LGA1851 ↔ Mainboard LGA1700', 57, 1, 0, 1, 2, 'socket', 'socket', 'NEQ', 'KHÔNG TƯƠNG THÍCH: CPU socket LGA1851 không thể lắp vào bo mạch chủ socket LGA1700 do khác biệt cơ học và chân cắm.', 'ACTIVE', 1, '2026-10-15 13:45:24', '2026-10-15 13:45:24'),
(1414, 'CPU LGA1851 ↔ Mainboard LGA1200', 57, 4, 0, 1, 2, 'socket', 'socket', 'NEQ', 'KHÔNG TƯƠNG THÍCH: CPU socket LGA1851 không thể lắp vào bo mạch chủ socket LGA1200 do khác biệt cơ học và chân cắm.', 'ACTIVE', 1, '2026-10-15 13:45:24', '2026-10-15 13:45:24'),
(1415, 'CPU LGA1851 ↔ Mainboard AM5', 57, 2, 0, 1, 2, 'socket', 'socket', 'NEQ', 'KHÔNG TƯƠNG THÍCH: CPU socket LGA1851 không thể lắp vào bo mạch chủ socket AM5 do khác biệt cơ học và chân cắm.', 'ACTIVE', 1, '2026-10-15 13:45:24', '2026-10-15 13:45:24'),
(1416, 'CPU LGA1851 ↔ Mainboard AM4', 57, 3, 0, 1, 2, 'socket', 'socket', 'NEQ', 'KHÔNG TƯƠNG THÍCH: CPU socket LGA1851 không thể lắp vào bo mạch chủ socket AM4 do khác biệt cơ học và chân cắm.', 'ACTIVE', 1, '2026-10-15 13:45:24', '2026-10-15 13:45:24'),
(1417, 'CPU LGA1700 ↔ Mainboard LGA1851', 1, 57, 0, 1, 2, 'socket', 'socket', 'NEQ', 'KHÔNG TƯƠNG THÍCH: CPU socket LGA1700 không thể lắp vào bo mạch chủ socket LGA1851 do khác biệt cơ học và chân cắm.', 'ACTIVE', 1, '2026-10-15 13:45:24', '2026-10-15 13:45:24'),
